package net.civeira.phylax.feature.observe.observedprobe.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class TimeoutMsVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property timeout ms of observed probe ")
  void test_timeout_ms_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> TimeoutMsVO.tryFrom(null));
    Assertions.assertEquals(1, TimeoutMsVO.from(1).getTimeoutMs());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> TimeoutMsVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", TimeoutMsVO.from(1).toString());
  }
}
